# --- your code ---
class IndexedSet:
    def __init__(self):
        self.values = []                 # slot -> value
        self.slot = {}                   # value -> slot

    def insert(self, x: int) -> bool:
        if x in self.slot:
            return False
        self.slot[x] = len(self.values)
        self.values.append(x)
        return True

    def remove(self, x: int) -> bool:
        if x not in self.slot:
            return False
        i, last = self.slot[x], self.values[-1]
        self.values[i], self.slot[last] = last, i   # the last value fills the gap
        self.values.pop()
        del self.slot[x]                 # after the move: x may be the last value
        return True

    def contains(self, x: int) -> bool:
        return x in self.slot

    def at(self, i: int) -> int:
        return self.values[i]

    def size(self) -> int:
        return len(self.values)


# --- provided: do not edit ---
def run_set(ops: list[list]) -> list:
    s = IndexedSet()
    return [getattr(s, name)(*args) for name, *args in ops]
